existing = """   cardiovascular-hypertension | Hypertension: diagnosis, staging and drug choice
   cardiovascular-stable-angina | Stable angina and chronic coronary syndrome
   cardiovascular-acs | Acute coronary syndrome: the first hour in the clinic
   cardiovascular-heart-failure | Heart failure with reduced and preserved ejection fraction
   cardiovascular-dyslipidaemia | Dyslipidaemia, risk stratification and statin choice
   cardiovascular-atrial-fibrillation | Atrial fibrillation: rate, rhythm and anticoagulation
   cardiovascular-ecg-interpretation | ECG reading for the family physician
   cardiovascular-pad-vte | Peripheral arterial disease and venous thromboembolism"""
tpl = open(sys.argv[1]).read()
json.dump({b:[f"{SUB}-{i}|{t}" for i,t,_,_ in v] for b,v in B.items()}, open(sys.argv[2]+"/cv_batches.json","w"), indent=1)
for b, ts in B.items():
    topics = "\n".join(f"   - `{SUB}-{i}` | {t} | {f} | scope: {s}" for i,t,f,s in ts)
    sib = "\n".join(f"   - {t}" for bb,v in B.items() if bb!=b for _,t,_,_ in v)
    rx = "|".join(f"{SUB}-{i}" for i,_,_,_ in ts)
    out = tpl.replace("{{SUBJECT}}",SUB).replace("{{BATCH}}",b).replace("{{TOPICS}}",topics).replace("{{EXISTING}}",existing).replace("{{SIBLINGS}}",sib).replace("{{BATCH_IDS_REGEX}}",rx).replace("{{PAPER}}",PAPER)
    open(f"{sys.argv[2]}/lib-{SUB}-{b}.md","w").write(out)
print(sum(len(v) for v in B.values()))
